sys_script_include.script:
// Script Include: AuditoriaAcessoService
// Camada: SERVIÇO LGPD — registra trilha de auditoria de operações sobre dados sensíveis
// em x_espaco_log_auditoria (RNF-07/RNF-09).
var AuditoriaAcessoService = Class.create();
AuditoriaAcessoService.prototype = {
    initialize: function() {
        this.TABLE = 'x_espaco_log_auditoria';
    },

    /**
     * Registra uma entrada de auditoria.
     * @param {string} acao - ex.: 'ANONIMIZACAO', 'CONSULTA', 'ALTERACAO'
     * @param {string} tabela - nome da tabela afetada
     * @param {string} registroId - sys_id do registro afetado
     * @param {string} detalhe - descrição da operação
     * @returns {string} sys_id do log criado
     */
    registrar: function(acao, tabela, registroId, detalhe) {
        var gr = new GlideRecord(this.TABLE);
        gr.initialize();
        gr.setValue('acao', acao);
        gr.setValue('tabela', tabela);
        gr.setValue('registro_id', registroId);
        gr.setValue('usuario', gs.getUserID());
        gr.setValue('detalhe', detalhe);
        gr.setValue('data_hora', new GlideDateTime());
        return gr.insert();
    },

    type: 'AuditoriaAcessoService'
};
